with valid as (select *, round(age * 1.1, 2) as age_scaled, coalesce(city, 'N/A') as city_clean from customers where signup_date >= to_date('2023-07-06') and city is not null) select *, round(credit_limit / sum(credit_limit) over (partition by country, city), 4) as credit_limit_share, cume_dist() over (partition by city order by age_scaled nulls first) as age_scaled_cume_dist, avg(age) over (partition by city, segment order by age_scaled, id rows between 6 preceding and 1 preceding) as age_avg_6_prior from valid where age <= 33;
